function expectedCrops(city,wallet){return city.cropLedger.map((e,index)=>({index,id:e.id,tick:e.tick,from:e.from,to:e.to,value:e.quantity,cropKind:e.kind,fromValue:e.fromValue,toValue:e.toValue,cash:e.cash,workers:e.workers,batches:e.batches,outputQuantity:e.outputQuantity})).reverse().filter(e=>!wallet||e.from===wallet||e.to===wallet);}
// Native summary toggles also carry kind/index; only semantic details cards are journal rows.
async function cropRows(selector){return evaluate(`[...document.querySelectorAll(${JSON.stringify(selector)})].map(e=>({index:Number(e.dataset.index),id:Number(e.dataset.id),tick:Number(e.dataset.tick),from:e.dataset.from,to:e.dataset.to,value:Number(e.dataset.value),cropKind:e.dataset.cropKind,fromValue:Number(e.dataset.fromValue),toValue:Number(e.dataset.toValue),cash:Number(e.dataset.cash),workers:Number(e.dataset.workers),batches:Number(e.dataset.batches),outputQuantity:Number(e.dataset.outputQuantity)}))`);}
async function inspectBusiness(city,f){await place(city,f.building);await metrics({'crop-stock':f.cropInventory,'crop-cost':f.cropCost,'production-tick':f.productionTick,workers:firmWorkerCount(city,f.id),cash:city.accounts[f.wallet]});const b=city.buildings.find(b=>b.id===f.building);assert.equal(await evaluate('Number(document.querySelector("#entity-content [data-context-metric=workers]").dataset.capacity)'),firmCapacity(b));assert.equal(await evaluate('document.querySelector("#entity-content").dataset.entityId'),String(b.id));if(f.zone==='F')await metrics({fertility:city.resources.fertility[b.cell],'yield-per-worker':Math.floor(24*city.resources.fertility[b.cell]/100)});if(f.zone==='I')await metrics({'recipe-input':2,'recipe-output':8,'available-batches':Math.min(firmWorkerCount(city,f.id),Math.floor(f.cropInventory/2))});if(isMarket(f)){const finance=ownerFinance(city,f.id);assert.ok(finance?.historyReconciled);await metrics({'crop-buy-price':200,'crop-factory-price':300,'crop-household-price':800,rent:firmRent(f),'realised-profit':finance.realizedProfit,'owner-household':f.owner.householdId,'owner-capital-contributed':f.owner.capitalContributed,'owner-capital-returned':f.owner.capitalReturned,'owner-withdrawn':f.owner.withdrawn,'owner-tax':f.owner.taxPaid,drawable:finance.withdrawAvailable});assert.equal(await evaluate(`document.querySelector('[data-owner-action="withdraw"][data-firm-id="${f.id}"]').disabled`),finance.withdrawAvailable<10000);}}
async function ownerHousehold(city,id){const h=city.households.find(h=>h.id===id);await place(city,h.home);await button(`#entity-content [data-household-id="${id}"]`);await until(`document.querySelector('#entity-content').dataset.scope==='household'&&document.querySelector('#entity-content').dataset.entityId==='${id}'`);const wage=employmentForHousehold(city,id),own=city.ownerLabor.filter(e=>e.householdId===id),combined=[...wage,...own],employed=combined.reduce((n,e)=>n+e.workers,0);await metrics({members:h.members,workforce:h.workforce,dependents:h.dependents,employed,unemployed:h.workforce-employed,cash:city.accounts[h.wallet]});assert.deepEqual(await evaluate('[...document.querySelectorAll("#entity-content .cx-owner-labor-row")].map(e=>({householdId:Number(e.dataset.householdId),firmId:Number(e.dataset.firmId),skill:e.dataset.skill,workers:Number(e.dataset.workers)}))'),own);assert.deepEqual(await evaluate('[...document.querySelectorAll("#entity-content .cx-skill-row")].map(e=>({skill:e.dataset.skill,total:Number(e.dataset.total),employed:Number(e.dataset.employed),unemployed:Number(e.dataset.unemployed)}))'),skills.map(skill=>{const employed=combined.filter(e=>e.skill===skill).reduce((n,e)=>n+e.workers,0);return{skill,total:h.workerSkills[skill],employed,unemployed:h.workerSkills[skill]-employed};}));}
async function growthMetrics(city){
  await page('city');const expected=industryGrowthStatus(city);await until('!!document.querySelector("[data-growth-status]")');assert.equal(await evaluate('document.querySelector("[data-growth-status]").dataset.growthReason'),expected.code);
  if(!await evaluate('document.querySelector("[data-growth-details]").open'))await button('[data-growth-details]>summary');
  const actual=await evaluate('Object.fromEntries([...document.querySelectorAll("[data-growth-status] [data-growth-metric]")].map(e=>[e.dataset.growthMetric,Number(e.dataset.value)]))');
  assert.deepEqual(actual,{'capital-available':expected.availableCapital,'capital-required':expected.requiredCapital,'sponsor-id':expected.sponsorFirmId??0,cash:expected.cash,'payroll-reserve':expected.payrollReserve,'tax-reserve':expected.taxReserve,'rent-reserve':expected.rentReserve,'working-reserve':expected.workingReserve,'crop-available':expected.cropAvailable,'funded-vacancies':expected.fundedVacancies});
  assert.ok((await evaluate('document.querySelector("[data-growth-message]").textContent')).trim().length>0);assert.deepEqual(await state(),city,'Opening actual growth diagnostics does not mutate the city');
}
